INSERT INTO people (slug, name, role, description, born, died) VALUES ('von-braun', 'Wernher von Braun', 'Rocket engineer', 'Technical director of the German V-2 program and member of the SS; brought to the United States in 1945, later led the Saturn V development at NASA.', '1912', '1977');
