INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('The U.S. Public Health Service Untreated Syphilis Study at Tuskegee', 'U.S. Centers for Disease Control and Prevention', NULL, NULL, 'website', 0, 'https://www.cdc.gov/tuskegee/', NULL, 'Official account by the successor agency, with timeline and background.', 'URL pending manual verification.');
