INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('Ethically Impossible: STD Research in Guatemala from 1946 to 1948', 'Presidential Commission for the Study of Bioethical Issues', 'Presidential Commission for the Study of Bioethical Issues', '2011-09', 'government_report', 1, NULL, NULL, 'Official investigation of separate Public Health Service experiments in which people were deliberately infected.', 'Print/offline source; no URL.');
INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('The Belmont Report: Ethical Principles and Guidelines for the Protection of Human Subjects of Research', 'U.S. Department of Health, Education, and Welfare', 'National Commission for the Protection of Human Subjects of Biomedical and Behavioral Research', '1979-04-18', 'government_report', 1, 'https://www.hhs.gov/ohrp/regulations-and-policy/belmont-report/index.html', NULL, 'Founding document of U.S. research ethics rules, written in response to abuses such as the Tuskegee study.', 'URL pending manual verification.');
INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('Supplementary Detailed Staff Reports on Intelligence Activities and the Rights of Americans, Book III', 'U.S. Government Printing Office', 'U.S. Senate (Church Committee)', '1976-04-23', 'government_report', 1, 'https://www.senate.gov/about/powers-procedures/investigations/church-committee.htm', NULL, 'Official committee report with a detailed chapter on COINTELPRO. The URL leads to the Senate overview page of the committee.', 'URL pending manual verification.');
INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('COINTELPRO (FBI Records: The Vault)', 'Federal Bureau of Investigation', NULL, NULL, 'archive_collection', 1, 'https://vault.fbi.gov/cointel-pro', NULL, 'Released FBI files on the programs, published by the FBI itself.', 'URL pending manual verification.');
INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('The Burglary: The Discovery of J. Edgar Hoover''s Secret FBI', 'Alfred A. Knopf', 'Betty Medsger', '2014', 'book', 0, NULL, NULL, 'Account of the 1971 Media burglary by the journalist who first reported on the stolen files.', 'Print/offline source; no URL.');
