INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('Tonkin Gulf Resolution (1964)', 'U.S. National Archives (Milestone Documents)', 'U.S. Congress', '1964-08-07', 'primary_document', 1, 'https://www.archives.gov/milestone-documents/tonkin-gulf-resolution', NULL, 'Text of the joint resolution with archival context.', 'URL pending manual verification.');
