INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('The Roswell Report: Fact vs. Fiction in the New Mexico Desert', 'U.S. Government Printing Office', 'Headquarters, United States Air Force', '1995', 'government_report', 1, NULL, NULL, 'Official Air Force report. Identifies the 1947 debris as part of a Project Mogul balloon train.', 'Print/offline source; no URL.');
