INSERT INTO sources (title, publisher, author, published_date, source_type, is_primary, url, last_checked, quality_note, notes) VALUES ('The Brown Book of the Hitler Terror and the Burning of the Reichstag', 'Victor Gollancz (English edition)', 'World Committee for the Victims of German Fascism', '1933', 'book', 1, NULL, NULL, 'Communist counter-publication that first accused the Nazis. A primary source for the history of the claim, not proof of it.', 'Print/offline source; no URL.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('tuskegee-syphilis-study', 'Tuskegee Syphilis Study', 'Forty years of withheld treatment by the U.S. Public Health Service', 'From 1932 to 1972 the U.S. Public Health Service observed the course of untreated syphilis in Black men in Macon County, Alabama. The men were not told their diagnosis and were not treated, even after penicillin became the standard cure. The study ended after it was exposed by the press in 1972.', 'About 600 men took part: roughly 400 with syphilis and about 200 without as a control group. They were told they were being treated for "bad blood" and received free meals, examinations and burial insurance. Researchers worked to keep them from receiving treatment elsewhere.', 'A Public Health Service employee, Peter Buxtun, raised objections internally from 1966. In July 1972 the Associated Press reporter Jean Heller made the study public. An advisory panel declared it ethically unjustified, and in 1997 President Bill Clinton formally apologised to the survivors.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"About 600 men took part: roughly 400 with syphilis and about 200 without as a control group. They were told they were being treated for \"bad blood\" and received free meals, examinations and burial insurance. Researchers worked to keep them from receiving treatment elsewhere."}]},{"type":"paragraph","content":[{"type":"text","text":"A Public Health Service employee, Peter Buxtun, raised objections internally from 1966. In July 1972 the Associated Press reporter Jean Heller made the study public. An advisory panel declared it ethically unjustified, and in 1997 President Bill Clinton formally apologised to the survivors."}]}]}', (SELECT id FROM categories WHERE slug = 'science-technology'), 'historically_documented', '/media/theories/tuskegee-syphilis-study.jpg', 'Doctor drawing blood from a participant of the Tuskegee syphilis study – National Archives at Atlanta (U.S. government), Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:Tuskegee-syphilis-study_doctor-injecting-subject.jpg', 'editorial', 1);
