INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'de', 'summary', 'Von 1932 bis 1972 beobachtete der US Public Health Service den Verlauf unbehandelter Syphilis bei schwarzen Männern im Macon County, Alabama. Die Männer erfuhren ihre Diagnose nicht und wurden nicht behandelt, auch nicht, als Penicillin zur Standardtherapie geworden war. Die Studie endete, nachdem die Presse sie 1972 öffentlich gemacht hatte.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'tuskegee-syphilis-study'), 'de', 'background', 'Etwa 600 Männer nahmen teil: rund 400 mit Syphilis und etwa 200 ohne als Kontrollgruppe. Man sagte ihnen, sie würden wegen „bad blood“ behandelt, und gab ihnen kostenlose Mahlzeiten, Untersuchungen und eine Bestattungsversicherung. Die Forscher sorgten dafür, dass sie auch anderswo keine Behandlung bekamen.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('cointelpro', 'COINTELPRO', 'The FBI''s secret programs against domestic political groups', 'From 1956 to 1971 the FBI ran a series of counterintelligence programs, known as COINTELPRO, to surveil, infiltrate, discredit and disrupt political organisations inside the United States. The programs became public after activists stole files from an FBI office in 1971 and were documented in detail by the Church Committee.', 'The first program, begun in 1956, targeted the Communist Party USA. Later programs were aimed at the Socialist Workers Party, white supremacist groups, Black nationalist and civil rights organisations, and the New Left. Methods included anonymous letters, planted press stories, informants and attempts to provoke conflict between groups.', 'On 8 March 1971 a group calling itself the Citizens’ Commission to Investigate the FBI broke into the FBI field office in Media, Pennsylvania, and sent the files to newspapers. One file carried the label "COINTELPRO". Director J. Edgar Hoover ended the programs in April 1971. The Church Committee published a detailed account in 1976.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first program, begun in 1956, targeted the Communist Party USA. Later programs were aimed at the Socialist Workers Party, white supremacist groups, Black nationalist and civil rights organisations, and the New Left. Methods included anonymous letters, planted press stories, informants and attempts to provoke conflict between groups."}]},{"type":"paragraph","content":[{"type":"text","text":"On 8 March 1971 a group calling itself the Citizens’ Commission to Investigate the FBI broke into the FBI field office in Media, Pennsylvania, and sent the files to newspapers. One file carried the label \"COINTELPRO\". Director J. Edgar Hoover ended the programs in April 1971. The Church Committee published a detailed account in 1976."}]}]}', (SELECT id FROM categories WHERE slug = 'intelligence-agencies'), 'historically_documented', '/media/theories/cointelpro.jpg', 'FBI COINTELPRO document on "neutralizing" the actress Jean Seberg – Richard W. Held / FBI, Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:COINTELPRO_-_Jean_Seberg.jpg', 'editorial', 1);
