INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'cointelpro'), 'COINTELPRO never really ended and continues unchanged today.', 'unverified', 3);
INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'cointelpro'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3), 'The programs were officially ended in 1971 and later oversight rules and congressional intelligence committees were created. Claims about later operations must be judged on their own evidence.', 0);
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Final Report of the Select Committee to Study Governmental Operations with Respect to Intelligence Activities, Book I' AND publisher = 'U.S. Government Printing Office' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'cointelpro'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3)), 'de', 'text', 'Die Programme wurden 1971 offiziell beendet, danach entstanden neue Aufsichtsregeln und Geheimdienstausschüsse im Kongress. Behauptungen über spätere Operationen müssen jeweils anhand eigener Belege geprüft werden.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'cointelpro') AND position = 3), 'de', 'text', 'COINTELPRO sei nie wirklich beendet worden und laufe bis heute unverändert weiter.');
