INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'de', 'title', 'COINTELPRO');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'de', 'subtitle', 'Die geheimen Programme des FBI gegen politische Gruppen im eigenen Land');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'de', 'summary', 'Von 1956 bis 1971 betrieb das FBI unter dem Namen COINTELPRO mehrere Spionageabwehrprogramme, um politische Organisationen in den USA zu überwachen, zu unterwandern, zu diskreditieren und zu stören. Die Programme wurden bekannt, nachdem Aktivisten 1971 Akten aus einem FBI-Büro entwendet hatten, und wurden vom Church Committee ausführlich dokumentiert.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'cointelpro'), 'de', 'background', 'Das erste Programm richtete sich ab 1956 gegen die Kommunistische Partei der USA. Spätere Programme zielten auf die Socialist Workers Party, rassistische weiße Gruppen, schwarze nationalistische und Bürgerrechtsorganisationen sowie die Neue Linke. Zu den Methoden gehörten anonyme Briefe, lancierte Pressegeschichten, Informanten und Versuche, Konflikte zwischen Gruppen zu schüren.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('gulf-of-tonkin-incident', 'Gulf of Tonkin Incident', 'The attack that never happened and the resolution that followed', 'In August 1964 the United States reported two attacks by North Vietnamese boats on U.S. destroyers in the Gulf of Tonkin. The first, on 2 August, took place. The second, reported on 4 August, almost certainly did not. Congress nevertheless passed the Tonkin Gulf Resolution, which became the legal basis for the escalation of the Vietnam War.', 'On 2 August 1964 the destroyer USS Maddox, on an intelligence patrol, was attacked by three North Vietnamese torpedo boats. On the night of 4 August the Maddox and USS Turner Joy reported a second attack in bad weather. President Johnson ordered air strikes the next day, and on 7 August Congress passed the resolution with only two votes against in the Senate.', 'Doubts about the second attack were raised soon afterwards, including by the commander on the scene. In 2005 the NSA declassified an internal study by its historian Robert J. Hanyok, which concluded that no attack occurred on 4 August and that intercepted signals had been mistranslated and selectively presented.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On 2 August 1964 the destroyer USS Maddox, on an intelligence patrol, was attacked by three North Vietnamese torpedo boats. On the night of 4 August the Maddox and USS Turner Joy reported a second attack in bad weather. President Johnson ordered air strikes the next day, and on 7 August Congress passed the resolution with only two votes against in the Senate."}]},{"type":"paragraph","content":[{"type":"text","text":"Doubts about the second attack were raised soon afterwards, including by the commander on the scene. In 2005 the NSA declassified an internal study by its historian Robert J. Hanyok, which concluded that no attack occurred on 4 August and that intercepted signals had been mistranslated and selectively presented."}]}]}', (SELECT id FROM categories WHERE slug = 'politics-power'), 'partially_supported', '/media/theories/gulf-of-tonkin-incident.jpg', 'The destroyer USS Maddox (DD-731) underway, early 1960s (NH 97900) – U.S. Navy / Naval History and Heritage Command, Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:USS_Maddox_(DD-731)_underway_at_sea,_circa_the_early_1960s_(NH_97900).jpg', 'editorial', 1);
