INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'Congress passed the Tonkin Gulf Resolution on 7 August 1964; it authorised the President to use armed force in Southeast Asia.', 'historically_documented', 2);
INSERT INTO evidence (source_id, theory_id, claim_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Tonkin Gulf Resolution (1964)' AND publisher = 'U.S. National Archives (Milestone Documents)' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 2), 'documents');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 2), 'de', 'text', 'Der Kongress verabschiedete am 7. August 1964 die Tonkin-Resolution, die den Präsidenten zum Einsatz von Streitkräften in Südostasien ermächtigte.');
INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'U.S. officials knowingly invented the 4 August attack as a pretext for war.', 'disputed', 3);
INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3), 'The NSA study shows that signals intelligence was mishandled and selectively presented. Historians disagree on whether decision-makers knew at the time that no attack had happened; the first reports from the destroyers were confused rather than invented.', 0);
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Skunks, Bogies, Silent Hounds, and the Flying Fish: The Gulf of Tonkin Mystery, 2–4 August 1964' AND publisher = 'Cryptologic Quarterly (National Security Agency)' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3)), 'refutes');
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Tonkin Gulf and the Escalation of the Vietnam War' AND publisher = 'University of North Carolina Press' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3)), 'de', 'text', 'Die NSA-Studie zeigt, dass Funkaufklärung falsch ausgewertet und selektiv dargestellt wurde. Historiker sind uneins, ob die Entscheidungsträger damals wussten, dass es keinen Angriff gab; die ersten Meldungen der Zerstörer waren eher verworren als erfunden.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident') AND position = 3), 'de', 'text', 'US-Verantwortliche hätten den Angriff vom 4. August wissentlich als Kriegsvorwand erfunden.');
INSERT INTO evidence (source_id, theory_id, relation, note) VALUES ((SELECT id FROM sources WHERE title = 'Tonkin Gulf and the Escalation of the Vietnam War' AND publisher = 'University of North Carolina Press' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'context', NULL);
