INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'de', 'subtitle', 'Der Angriff, den es nie gab, und die Resolution, die folgte');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'de', 'summary', 'Im August 1964 meldeten die USA zwei Angriffe nordvietnamesischer Boote auf US-Zerstörer im Golf von Tonkin. Der erste am 2. August fand statt. Der zweite, gemeldet am 4. August, fand mit großer Wahrscheinlichkeit nicht statt. Der Kongress verabschiedete dennoch die Tonkin-Resolution, die zur rechtlichen Grundlage für die Ausweitung des Vietnamkriegs wurde.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'gulf-of-tonkin-incident'), 'de', 'background', 'Am 2. August 1964 wurde der Zerstörer USS Maddox auf einer Aufklärungsfahrt von drei nordvietnamesischen Torpedobooten angegriffen. In der Nacht zum 4. August meldeten die Maddox und die USS Turner Joy bei schlechtem Wetter einen zweiten Angriff. Präsident Johnson ordnete am nächsten Tag Luftangriffe an, und am 7. August verabschiedete der Kongress die Resolution mit nur zwei Gegenstimmen im Senat.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('operation-paperclip', 'Operation Paperclip', 'How the United States recruited German scientists after 1945', 'After the Second World War the United States brought more than 1,600 German scientists, engineers and technicians to America under a program known as Operation Paperclip. Among them were former members of the Nazi Party and the SS. Their pasts were often played down so that they could work and immigrate.', 'The program was administered by the Joint Intelligence Objectives Agency. Its aim was to use German expertise in rocketry, aviation, chemistry and medicine and to keep it from the Soviet Union. The best-known recruit was Wernher von Braun, who had led the V-2 rocket program and later directed the development of the Saturn V moon rocket.', 'The program was partly public from the late 1940s, but the extent to which background checks were softened only became known through later research based on Freedom of Information Act requests, notably by the journalist Linda Hunt (1985 onwards). The case of Arthur Rudolph, who left the United States in 1984, drew wide attention.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The program was administered by the Joint Intelligence Objectives Agency. Its aim was to use German expertise in rocketry, aviation, chemistry and medicine and to keep it from the Soviet Union. The best-known recruit was Wernher von Braun, who had led the V-2 rocket program and later directed the development of the Saturn V moon rocket."}]},{"type":"paragraph","content":[{"type":"text","text":"The program was partly public from the late 1940s, but the extent to which background checks were softened only became known through later research based on Freedom of Information Act requests, notably by the journalist Linda Hunt (1985 onwards). The case of Arthur Rudolph, who left the United States in 1984, drew wide attention."}]}]}', (SELECT id FROM categories WHERE slug = 'secret-operations'), 'historically_documented', '/media/theories/operation-paperclip.jpg', 'Operation Paperclip team of German rocket scientists at Fort Bliss, Texas (1946) – U.S. Army / NASA, Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:Project_Paperclip_Team_at_Fort_Bliss.jpg', 'editorial', 1);
