INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Von Braun: Dreamer of Space, Engineer of War' AND publisher = 'Alfred A. Knopf' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'operation-paperclip'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 3)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 3)), 'de', 'text', 'Deutsche Ingenieure hatten leitende Posten, vor allem im Raketenprogramm in Huntsville, doch die NASA war eine zivile Behörde unter amerikanischer politischer Kontrolle. Es gibt keinen Beleg für eine verborgene Agenda.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'operation-paperclip') AND position = 3), 'de', 'text', 'Ehemalige Nazis hätten die NASA heimlich kontrolliert und über sie eine verborgene Agenda verfolgt.');
