INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'de', 'summary', 'Nach dem Zweiten Weltkrieg holten die USA im Rahmen der Operation Paperclip mehr als 1.600 deutsche Wissenschaftler, Ingenieure und Techniker ins Land. Unter ihnen waren frühere Mitglieder der NSDAP und der SS. Ihre Vergangenheit wurde oft heruntergespielt, damit sie arbeiten und einwandern konnten.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'operation-paperclip'), 'de', 'background', 'Verwaltet wurde das Programm von der Joint Intelligence Objectives Agency. Ziel war es, deutsches Fachwissen in Raketentechnik, Luftfahrt, Chemie und Medizin zu nutzen und der Sowjetunion vorzuenthalten. Der bekannteste Angeworbene war Wernher von Braun, der das V-2-Programm geleitet hatte und später die Entwicklung der Mondrakete Saturn V führte.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('roswell-incident', 'Roswell Incident', 'A 1947 debris find and the alien crash story it became', 'In July 1947 the U.S. Army Air Forces at Roswell, New Mexico, announced that they had recovered a "flying disc", and corrected this the next day to a weather balloon. Decades later the event became the best-known alien crash story. Air Force investigations in the 1990s traced the debris to Project Mogul, a secret balloon program.', 'A rancher found debris of foil, rubber, tape and sticks on a ranch north-west of Roswell. On 8 July 1947 the press office of Roswell Army Air Field issued its "flying disc" statement; on the following day the commander of the Eighth Air Force presented the material as the remains of a weather balloon. Project Mogul used trains of balloons to listen for Soviet nuclear tests and was secret at the time.', 'The story was largely forgotten until 1978, when a former intelligence officer, Jesse Marcel, gave interviews about the debris. The 1980 book "The Roswell Incident" by Charles Berlitz and William L. Moore made it widely known. Accounts of recovered alien bodies were added in the following years.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A rancher found debris of foil, rubber, tape and sticks on a ranch north-west of Roswell. On 8 July 1947 the press office of Roswell Army Air Field issued its \"flying disc\" statement; on the following day the commander of the Eighth Air Force presented the material as the remains of a weather balloon. Project Mogul used trains of balloons to listen for Soviet nuclear tests and was secret at the time."}]},{"type":"paragraph","content":[{"type":"text","text":"The story was largely forgotten until 1978, when a former intelligence officer, Jesse Marcel, gave interviews about the debris. The 1980 book \"The Roswell Incident\" by Charles Berlitz and William L. Moore made it widely known. Accounts of recovered alien bodies were added in the following years."}]}]}', (SELECT id FROM categories WHERE slug = 'space-ufos'), 'debunked', '/media/theories/roswell-incident.jpg', 'Roswell Daily Record front page, 8 July 1947 – Roswell Daily Record, Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:Roswell_Daily_Record._July_8,_1947._RAAF_Captures_Flying_Saucer_On_Ranch_in_Roswell_Region._Top_of_front_page.jpg', 'editorial', 1);
