INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'roswell-incident'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 2), 'Two Air Force reports and a 2024 Department of Defense review found no evidence of an alien craft. The accounts of bodies appeared decades later and match 1950s tests with anthropomorphic dummies and unrelated accidents.', 0);
