INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 2)), 'de', 'text', 'Zwei Berichte der Air Force und eine Prüfung des US-Verteidigungsministeriums von 2024 fanden keinen Beleg für ein außerirdisches Fluggerät. Die Berichte über Leichen tauchten erst Jahrzehnte später auf und passen zu Tests mit Puppen in den 1950er-Jahren und zu anderen Unfällen.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 2), 'de', 'text', 'Bei Roswell sei ein außerirdisches Raumschiff abgestürzt und die Leichen der Besatzung seien geborgen worden.');
