INSERT INTO evidence (source_id, theory_id, claim_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Results of a Search for Records Concerning the 1947 Crash Near Roswell, New Mexico (GAO/NSIAD-95-187)' AND publisher = 'U.S. General Accounting Office' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'roswell-incident'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 3), 'documents');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 3), 'de', 'text', 'Einige Verwaltungsunterlagen des Roswell Army Air Field aus dieser Zeit wurden vernichtet.');
INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'roswell-incident'), 'The destroyed records prove a cover-up of an alien crash.', 'unverified', 4);
INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'roswell-incident'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4), 'The General Accounting Office could not determine who destroyed the records or why. Their loss alone is not evidence of what happened in 1947.', 1);
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Results of a Search for Records Concerning the 1947 Crash Near Roswell, New Mexico (GAO/NSIAD-95-187)' AND publisher = 'U.S. General Accounting Office' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'roswell-incident'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4)), 'de', 'text', 'Der Rechnungshof des Kongresses konnte nicht klären, wer die Unterlagen vernichtete oder warum. Ihr Fehlen allein ist kein Beleg dafür, was 1947 geschah.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'roswell-incident') AND position = 4), 'de', 'text', 'Die vernichteten Unterlagen bewiesen die Vertuschung eines Alien-Absturzes.');
