INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'de', 'subtitle', 'Ein Trümmerfund von 1947 und die Alien-Absturzgeschichte, die daraus wurde');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'de', 'summary', 'Im Juli 1947 gaben die US Army Air Forces in Roswell, New Mexico, bekannt, eine „fliegende Scheibe“ geborgen zu haben, und korrigierten dies am nächsten Tag zu einem Wetterballon. Jahrzehnte später wurde daraus die bekannteste Geschichte über einen Alien-Absturz. Untersuchungen der Air Force in den 1990er-Jahren führten die Trümmer auf Project Mogul zurück, ein geheimes Ballonprogramm.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'roswell-incident'), 'de', 'background', 'Ein Farmer fand nordwestlich von Roswell Trümmer aus Folie, Gummi, Klebeband und Stäben. Am 8. Juli 1947 verbreitete die Pressestelle des Roswell Army Air Field die Meldung von der „fliegenden Scheibe“; am Tag darauf präsentierte der Kommandeur der Eighth Air Force das Material als Reste eines Wetterballons. Project Mogul nutzte Ballonketten, um sowjetische Atomtests abzuhören, und war damals geheim.');
INSERT INTO theories (slug, title, subtitle, summary, background, origin_story, body_json, category_id, evidence_status, image_path, image_credit, origin, is_published) VALUES ('reichstag-fire', 'Reichstag Fire', 'Who set the German parliament on fire in 1933?', 'On the night of 27 February 1933 the Reichstag building in Berlin burned. The Dutch council communist Marinus van der Lubbe was arrested at the scene. The new Nazi government used the fire to suspend basic rights the next day. Whether van der Lubbe acted alone or the Nazis were involved is still debated by historians.', 'Adolf Hitler had been appointed Chancellor four weeks earlier. On 28 February President Hindenburg signed the Reichstag Fire Decree, which suspended freedom of the press, assembly and expression and allowed arrests without trial. Thousands of communists and other opponents were detained in the following weeks, shortly before the election of 5 March 1933.', 'The Nazi leadership immediately claimed the fire was the signal for a communist uprising. In 1933 an exile group published the "Brown Book", which accused the Nazis of setting the fire themselves. At the Leipzig trial van der Lubbe was sentenced to death, while the four communist co-defendants were acquitted. Since Fritz Tobias argued in 1962 that van der Lubbe acted alone, historians have been divided.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Adolf Hitler had been appointed Chancellor four weeks earlier. On 28 February President Hindenburg signed the Reichstag Fire Decree, which suspended freedom of the press, assembly and expression and allowed arrests without trial. Thousands of communists and other opponents were detained in the following weeks, shortly before the election of 5 March 1933."}]},{"type":"paragraph","content":[{"type":"text","text":"The Nazi leadership immediately claimed the fire was the signal for a communist uprising. In 1933 an exile group published the \"Brown Book\", which accused the Nazis of setting the fire themselves. At the Leipzig trial van der Lubbe was sentenced to death, while the four communist co-defendants were acquitted. Since Fritz Tobias argued in 1962 that van der Lubbe acted alone, historians have been divided."}]}]}', (SELECT id FROM categories WHERE slug = 'history'), 'disputed', '/media/theories/reichstag-fire.jpg', 'Firemen at the burning Reichstag building, February 1933 (NARA 535790) – U.S. National Archives (NARA), Public domain, via Wikimedia Commons https://commons.wikimedia.org/wiki/File:Firemen_work_on_the_burning_Reichstag_Building_in_February,_1933,_after_fire_broke_out_simultaneously_at_20_places...._-_NARA_-_535790.tif', 'editorial', 1);
