INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 2)), 'de', 'text', 'Es fanden sich keine Belege für einen geplanten Aufstand, und das Leipziger Gericht sprach die vier kommunistischen Mitangeklagten im Dezember 1933 frei.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 2), 'de', 'text', 'Der Brand sei Teil eines geplanten kommunistischen Aufstands gewesen, wie die NS-Regierung behauptete.');
INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'Van der Lubbe set the fire alone.', 'disputed', 3);
INSERT INTO evidence (source_id, theory_id, claim_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Der Reichstagsbrand: Legende und Wirklichkeit' AND publisher = 'Grote' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3), 'context');
INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3), 'Some historians argue that the extent of the fire and the circumstances point to helpers; the question has not been settled.', 1);
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Burning the Reichstag: An Investigation into the Third Reich''s Enduring Mystery' AND publisher = 'Oxford University Press' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3)), 'de', 'text', 'Einige Historiker meinen, Ausmaß und Umstände des Brandes sprächen für Helfer; die Frage ist nicht geklärt.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 3), 'de', 'text', 'Van der Lubbe habe den Brand allein gelegt.');
INSERT INTO claims (theory_id, text, evidence_status, position) VALUES ((SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'The Nazis set the fire themselves to seize power.', 'disputed', 4);
INSERT INTO evidence (source_id, theory_id, claim_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'The Brown Book of the Hitler Terror and the Burning of the Reichstag' AND publisher = 'Victor Gollancz (English edition)' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4), 'context');
INSERT INTO evidence (source_id, theory_id, claim_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Burning the Reichstag: An Investigation into the Third Reich''s Enduring Mystery' AND publisher = 'Oxford University Press' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4), 'context');
INSERT INTO counter_arguments (theory_id, claim_id, text, position) VALUES ((SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4), 'No direct document proves that the Nazis set the fire. Historians such as Fritz Tobias and Hans Mommsen argued for a lone perpetrator; the debate continues.', 2);
INSERT INTO evidence (source_id, theory_id, counter_argument_id, relation) VALUES ((SELECT id FROM sources WHERE title = 'Der Reichstagsbrand: Legende und Wirklichkeit' AND publisher = 'Grote' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4)), 'refutes');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('counter_argument', (SELECT id FROM counter_arguments WHERE claim_id = (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4)), 'de', 'text', 'Kein Dokument beweist direkt, dass die Nationalsozialisten den Brand legten. Historiker wie Fritz Tobias und Hans Mommsen vertraten die Alleintäterthese; die Debatte dauert an.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('claim', (SELECT id FROM claims WHERE theory_id = (SELECT id FROM theories WHERE slug = 'reichstag-fire') AND position = 4), 'de', 'text', 'Die Nationalsozialisten hätten den Brand selbst gelegt, um die Macht zu ergreifen.');
INSERT INTO evidence (source_id, theory_id, relation, note) VALUES ((SELECT id FROM sources WHERE title = 'Verordnung des Reichspräsidenten zum Schutz von Volk und Staat (28 February 1933)' AND publisher = 'Reichsgesetzblatt 1933 I, p. 83' ORDER BY id LIMIT 1), (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'context', 'Legal consequence of the fire.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'de', 'title', 'Reichstagsbrand');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'de', 'subtitle', 'Wer hat 1933 das deutsche Parlament angezündet?');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'de', 'summary', 'In der Nacht zum 28. Februar 1933 brannte das Reichstagsgebäude in Berlin. Der niederländische Rätekommunist Marinus van der Lubbe wurde am Tatort festgenommen. Die neue NS-Regierung nutzte den Brand, um schon am nächsten Tag die Grundrechte außer Kraft zu setzen. Ob van der Lubbe allein handelte oder die Nationalsozialisten beteiligt waren, ist unter Historikern bis heute umstritten.');
INSERT OR REPLACE INTO translations (entity_type, entity_id, locale, field, value) VALUES ('theory', (SELECT id FROM theories WHERE slug = 'reichstag-fire'), 'de', 'background', 'Adolf Hitler war vier Wochen zuvor zum Reichskanzler ernannt worden. Am 28. Februar unterzeichnete Reichspräsident Hindenburg die Reichstagsbrandverordnung, die Presse-, Versammlungs- und Meinungsfreiheit aufhob und Verhaftungen ohne Gerichtsverfahren erlaubte. In den folgenden Wochen, kurz vor der Wahl am 5. März 1933, wurden Tausende Kommunisten und andere Gegner festgenommen.');
